<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/customer.php';
$type=$_GET['type']??'customer';if(!in_array($type,['customer','admin','reseller'],true))$type='customer';$message='Se o endereço estiver cadastrado, enviaremos um link de recuperação.';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));if(filter_var($email,FILTER_VALIDATE_EMAIL)){$table=$type==='admin'?'admins':($type==='reseller'?'reseller_accounts':'customer_accounts');$q=db()->prepare("SELECT id,email FROM {$table} WHERE email=? LIMIT 1");$q->execute([$email]);$a=$q->fetch();if($a){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$q=db()->prepare("INSERT INTO password_resets(account_type,account_id,token_hash,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))");$q->execute([$type,$a['id'],$hash]);$url=app_url('reset-password.php?token='.$token.'&type='.$type);@send_app_email($email,'Recuperação de senha - Edtek Review',mail_template('Redefina sua senha','Recebemos uma solicitação para alterar a senha da sua conta. O link expira em uma hora.',$url,'Criar nova senha'));}}header('Location: forgot-password.php?type='.$type.'&sent=1');exit;}
layout_start('Recuperar senha');
?><section class="narrow"><h1>Esqueceu sua senha?</h1><p>Informe o e-mail cadastrado para receber um link de recuperação.</p><?php if(isset($_GET['sent'])):?><div class="notice"><?=e($message)?></div><?php endif;?><form method="post" class="panel"><?=client_csrf_field()?><label>E-mail<input type="email" name="email" required autocomplete="email"></label><button>Enviar link</button></form><p><a href="<?=$type==='admin'?'login.php':'customer-login.php'?>">Voltar ao login</a></p></section><?php layout_end();?>